out={}
for reg,(anker,skin,adj,L) in R.items():
    for (soort,NAME,ROLE,OUT,MOOD,PORT,FRONT,BACK) in L:
        sid='trn_%s_%s'%(reg,'venator' if soort=='venator' else ('miles' if soort=='miles' else 'explorator'))
        prompt=g.TPL.format(NAME=NAME,ROLE=ROLE,OUTFIT=OUT,SKIN=skin,MOOD=MOOD,PORT=PORT,FRONT=FRONT,BACK=BACK)
        slug=NAME.lower().replace(' ','_')
        out[sid]={'B':prompt,'anker':anker,'portrait':slug}
json.dump(out,open(os.path.join(S,'srv','trn2.json'),'w',encoding='utf-8'),ensure_ascii=False)
print(len(out),list(out)[:3])
